// Quiet hours in Europe/Lisbon. Correct across the summer offset: we ask the
// Intl API for the wall-clock hour in Lisbon rather than trusting server time.
const u = $('Load User').first().json;
const msg = $('When Called').first().json;
const fmt = new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Lisbon',
  hour: '2-digit', minute: '2-digit', hour12: false });
const [h, m] = fmt.format(new Date()).split(':').map(Number);
const nowMin = h * 60 + m;
const toMin = s => { const [a,b] = String(s).split(':').map(Number); return a*60+b; };
const start = toMin(u.quiet_hours_start), end = toMin(u.quiet_hours_end);
// Quiet window may cross midnight (22:00 -> 08:00).
const inQuiet = start < end ? (nowMin >= start && nowMin < end)
                            : (nowMin >= start || nowMin < end);
const high = msg.priority === 'high';
return [{ json: { ...msg, user_id: u.id, chat_id: u.telegram_chat_id,
  paused: u.paused, send: (!inQuiet || high) && !(u.paused && !high),
  reason: u.paused && !high ? 'paused' : (inQuiet && !high ? 'quiet_hours' : 'send') } }];

